    instructions_ru = '[{"russian":"Лягте на фоам-роллер","polski":"Połóż się na wałku piankowym","svenska":"Lägg dig på foam rollern","čeština":"Lehněte si na pěnový válec","slovenčina":"Ľahnite si na penový valec","suomi":"Makaa vaahtomuovitelalle","italiano":"Sdraiati sul foam roller","deutsch":"Legen Sie sich auf die Schaumstoffrolle","français\r":"Allongez-vous sur le rouleau en mousse"},{"russian":"Медленно катайте роллер под мышцами","polski":"Powoli przesuwaj wałek pod mięśniami.","svenska":"Rulla rullen långsamt under dina muskler.","čeština":"Válec pomalu rolujte pod svaly.","slovenčina":"Valčekom pomaly rolujte pod svalmi.","suomi":"Pyöritä rullaa hitaasti lihasten alle.","italiano":"Fai rotolare lentamente il rullo sotto i muscoli.","deutsch":"Rollen Sie die Rolle langsam unter Ihren Muskeln.","français\r":"Faites rouler lentement le rouleau sous vos muscles."},{"russian":"Остановитесь на болезненных точках","polski":"Skup się na punktach bólu","svenska":"Fokusera på smärtpunkter","čeština":"Zaměřte se na bolestivé body","slovenčina":"Zamerajte sa na bolestivé body","suomi":"Keskity kipupisteisiin","italiano":"Concentrarsi sui punti dolenti","deutsch":"Konzentrieren Sie sich auf die Schmerzpunkte","français\r":"Se concentrer sur les points sensibles"},{"russian":"Держите давление 30-60 секунд","polski":"Utrzymaj nacisk przez 30-60 sekund","svenska":"Håll trycket i 30-60 sekunder","čeština":"Držte tlak po dobu 30-60 sekund","slovenčina":"Držte tlak 30-60 sekúnd","suomi":"Pidä painetta 30-60 sekuntia","italiano":"Mantenere la pressione per 30-60 secondi","deutsch":"Halten Sie den Druck 30-60 Sekunden lang","français\r":"Maintenez la pression pendant 30 à 60 secondes"},{"russian":"Повторите для всех групп мышц","polski":"Powtórz dla wszystkich grup mięśni.","svenska":"Upprepa för alla muskelgrupper.","čeština":"Opakujte pro všechny svalové skupiny.","slovenčina":"Opakujte pre všetky svalové skupiny.","suomi":"Toista kaikille lihasryhmille.","italiano":"Ripetere l''esercizio per tutti i gruppi muscolari.","deutsch":"Wiederholen Sie dies für alle Muskelgruppen.","français\r":"Répétez l’opération pour tous les groupes musculaires."}]',
